top=[(5,4),(5,6),(6,0),(6,5),(6,7),(6,9),(7,5),(9,5),(9,9)]
bot=[(1,2),(1,5),(5,5),(6,2),(7,0),(7,7),(7,9),(8,5),(9,2),(9,5),(9,9),(10,1),(10,3)]
def comps(points, diagonals=False):
    pts=set(points); out=[]
    while pts:
        seed=pts.pop(); stack=[seed]; cc={seed}
        while stack:
            r,c=stack.pop()
            for dr in (-1,0,1):
                for dc in (-1,0,1):
                    if not (dr or dc) or (not diagonals and dr and dc): continue
                    q=(r+dr,c+dc)
                    if q in pts: pts.remove(q);cc.add(q);stack.append(q)
        out.append(cc)
    return sorted(out,key=len,reverse=True)
for label,pts in [('top',top),('bot',bot)]:
    for dia in [False,True]:
        cs=comps(pts,dia)
        print(label,'8' if dia else '4',[(len(x),sorted(x)) for x in cs])

